// --- COMPONENT LOGIC ---
const ChunkyText = ({
  text,
  color,
  shadowColor,
  size,
  s,
  delay,
  frame,
  fps,
}: {
  text: string;
  color: string;
  shadowColor: string;
  size: number;
  s: number;
  delay: number;
  frame: number;
  fps: number;
}) => {
  const pop = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 100 },
  });

  const extrudeDepth = 15 * s;
  const shadowArr = [];
  for (let i = 1; i <= Math.floor(extrudeDepth); i++) {
    shadowArr.push(`${i}px ${i}px 0 ${shadowColor}`);
  }
  const textShadow = shadowArr.join(",");

  const stickerOutline = [
    `drop-shadow(0px 0px ${4 * s}px white)`,
    `drop-shadow(0px 0px ${4 * s}px white)`,
    `drop-shadow(0px 0px ${4 * s}px white)`,
    `drop-shadow(0px 0px ${4 * s}px white)`,
  ].join(" ");

  return (
    <div
      style={{
        position: "relative",
        fontSize: size * s,
        fontFamily: lilitaFamily,
        lineHeight: 1,
        letterSpacing: `${4 * s}px`,
        transform: `scale(${pop})`,
        opacity: pop > 0 ? 1 : 0,
        transition: "none",
        filter: stickerOutline,
      }}
    >
      <div
        style={{
          color: color,
          textShadow: textShadow,
          WebkitTextStroke: `${3 * s}px white`,
          transition: "none",
        }}
      >
        {text}
      </div>
    </div>
  );
};

const HumanResource: React.FC<HumanResourceProps> = ({
  backgroundColor = "#fdf6e9",
  transparentBackground = false,
  durationInSeconds = 10,
  titlePart1 = "HUMAN",
  titlePart2 = "RESOURCE",
  primaryColor = "#F39C12", // Yellow/Orange
  secondaryColor = "#794c25", // Brown
  title1Shadow = "#d68910", // Darker orange
  title2Shadow = "#4a2c14", // Darker brown
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const icons = [
    IconUser,
    IconDoc,
    IconGlobe,
    IconChart,
    IconCog,
    IconSearch,
    IconMoney,
    IconNetwork,
  ];
  const numItems = 12;

  const R = width * 0.38;
  const orbitAngle = interpolate(frame, [0, fps * 15], [0, Math.PI * 2]);
  
  const ringScale = spring({
    frame: frame - 5,
    fps,
    config: { damping: 15 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {/* Background Dashed Ring */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: `translate(-50%, -50%) rotate(${frame * 0.2}deg) scale(${ringScale})`,
          width: R * 2,
          height: R * 2,
          opacity: ringScale > 0 ? 1 : 0,
          transition: "none",
        }}
      >
        <svg
          width="100%"
          height="100%"
          viewBox="0 0 100 100"
          style={{ transition: "none" }}
        >
          <circle
            cx="50"
            cy="50"
            r="49"
            fill="none"
            stroke={secondaryColor}
            strokeWidth={0.5}
            strokeDasharray="2 4"
            opacity={0.3}
            style={{ transition: "none" }}
          />
        </svg>
      </div>

      {/* Orbiting Icons */}
      {Array.from({ length: numItems }).map((_, i) => {
        const Icon = icons[i % icons.length];
        const angle = (i / numItems) * Math.PI * 2 + orbitAngle;
        const x = width / 2 + Math.cos(angle) * R;
        const y = height / 2 + Math.sin(angle) * R;

        const iconPop = spring({
          frame: frame - i * 3 - 15,
          fps,
          config: { damping: 12 },
        });

        // Inverse rotate the icon so it stays upright despite the orbit
        const inverseRotation = -orbitAngle * (180 / Math.PI);

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: x,
              top: y,
              transform: `translate(-50%, -50%) scale(${iconPop}) rotate(${inverseRotation}deg)`,
              opacity: iconPop > 0 ? 1 : 0,
              transition: "none",
            }}
          >
            <Icon color={secondaryColor} accent={primaryColor} size={90 * s} />
          </div>
        );
      })}

      {/* Central 3D Text */}
      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          transform: "translate(-50%, -50%)",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: `${5 * s}px`,
          transition: "none",
        }}
      >
        <ChunkyText
          text={titlePart1}
          color={primaryColor}
          shadowColor={title1Shadow}
          size={160}
          s={s}
          delay={40}
          frame={frame}
          fps={fps}
        />
        <ChunkyText
          text={titlePart2}
          color={secondaryColor}
          shadowColor={title2Shadow}
          size={150}
          s={s}
          delay={45}
          frame={frame}
          fps={fps}
        />
      </div>
    </AbsoluteFill>
  );
};

export default HumanResource;